	if err != nil {
		return nil, err
	}

	return &SpecSchedule{
		Second: 1 << seconds.min,
		Minute: minute,
		Hour:   hour,
		Dom:    dayofmonth,
		Month:  month,
		Dow:    dayofweek,
	}, nil
}

